def entry(n,part,task,answer,hint,steps,views,probes,refs=(98,99)):
    c=make(n,part=part,pages=[270],question=task,answer=answer,hint=hint,steps=steps,frames=[views[0],*views[:3]],cases=views,prompts=probes)
    c['review']['reviewer']='Атанасян 7–9, издание 2023, печатная с. 270; исходные пункты, координаты и ответы на с. 399 перепроверены уравнениями и измерениями собственных рисунков.'
    c['help'][1].update(theoryIds=[f'atanasyan-7-9-theory-{r}-part-1' for r in refs],text='Открой уравнение нужной фигуры. Перенеси координаты из своего рисунка в формулу и проверь ими исходное условие.')
    return c


def shape(label,points,lines=(),edges=(),circles=()):
    ext=dict(points)
    for name,center,q in circles:
        r=float(q)**.5;ext[name]=center;ext['_'+name+'a']=(center[0]-r,center[1]-r);ext['_'+name+'b']=(center[0]+r,center[1]+r)
    return chart(label,circles,points,edges,[section(eq,ext) for eq in lines])


def classify():
    rows=[]
    for part,formula,center,q,newcenter,newq,step in [
        ('а','(x−1)²+(y+2)²=25',(1,-2),25,(-1,2),9,'Скобки уже имеют нужный вид: x−1 и y−(−2).'),
        ('б','x²+(y+7)²=1',(0,-7),1,(-3,0),4,'Первая скобка равна x−0. Ордината центра −7, поскольку вторая скобка y+7.'),
        ('в','x²+y²+8x−4y+40=0',(-4,2),-20,(-4,2),4,'Выдели квадраты: x²+8x=(x+4)²−16 и y²−4y=(y−2)²−4.'),
        ('г','x²+y²−2x+4y−20=0',(1,-2),25,(1,-2),1,'Выдели квадраты: x²−2x=(x−1)²−1 и y²+4y=(y+2)²−4.'),
        ('д','x²+y²−4x−2y+1=0',(2,1),4,(2,-1),9,'Выдели квадраты: x²−4x=(x−2)²−4 и y²−2y=(y−1)²−1.')]:
        good=q>0;num=int(newq**.5);hint='Приведи левую часть к сумме двух квадратов. Сначала проверь знак правой части. Если она положительна, различай радиус и квадрат радиуса.'
        first=shape('Точка, где сумма квадратов минимальна',{'S':center})
        if good:
            r=int(q**.5);v=(center[0]+r,center[1]);original=shape('Исходная окружность и радиус',{'P':v},edges=[('S','P')],circles=[('S',center,q)])
            reason=f'{equation(center,q)}. Центр S={text(center)}, радиус {r}. Минимальная сумма квадратов равна 0 в S, а при смещении на {r} вправо достигает {q}.'
            examples=[f'{center[0]};{center[1]};{r}',f'{center[0]}; {center[1]}; {r}',f'{text(center)};{r}',f'{text(center)}; {r}']
        else:
            original=shape('Центр суммы квадратов, точек окружности нет',{'S':center,'T':(-3,2)},edges=[('S','T')]);reason='Получается (x+4)²+(y−2)²=−20. Сумма квадратов действительных чисел неотрицательна; ни одной точки и никакой окружности нет.';examples=['нет','нет окружности','не является окружностью','нет решений']
        new=shape('Новая окружность с положительной правой частью',{'U':(newcenter[0],newcenter[1]+num)},edges=[('S','U')],circles=[('S',newcenter,newq)])
        steps=[('Собери квадраты',step+' Получаем '+equation(center,q)+'.','Координату центра вычитают внутри соответствующей скобки.'),('Проверь существование окружности',reason,'У действительной окружности положительного радиуса правая часть строго положительна.'),('Рассмотри новые данные',f'Для нового равенства {equation(newcenter,newq)} центр S={text(newcenter)}, радиус {num}. Это проверяется точкой U={text((newcenter[0],newcenter[1]+num))}.','Извлекай квадратный корень только после проверки знака.')]
        c=entry(1087,part,'Определи, описывает ли равенство '+formula+' окружность. Если да, назови центр и радиус.',reason,hint,steps,[first,original,new],[('Какая правая часть получилась после выделения квадратов?',str(q),'Перенеси постоянные слагаемые направо.'),('Каков радиус новой окружности?',str(num),'Из положительной правой части извлеки корень.')],(98,))
        c['answer']=dict(mode='exact',accepted=examples,prompt='Введи координаты центра и радиус в порядке x;y;r. Если действительной окружности нет, напиши «нет».',feedback=hint);rows.append(c)
    return rows


def through_points(n,part=None):
    if n==1088:
        points={'A':(3,0),'B':(-1,2)};src='Окружность проходит через A=(3;0), B=(−1;2), а её центр лежит на y=x+2.'
        center=(3,5);q=25;constraints=[(1,-1,2),(2,-1,-1)]
        steps=[('Построй условие равенства радиусов','Центр S=(u;v) одинаково удалён от A и B. Раскрыв SA²=SB², получаем v=2u−1. Геометрически это серединный перпендикуляр к AB.','Первое уравнение задаёт целую прямую возможных центров.'),('Пересеки две прямые','Второе условие v=u+2. Решаем u+2=2u−1: u=3 и v=5. Радиус SA=5, поэтому (x−3)²+(y−5)²=25. Для B квадрат расстояния 16+9=25.','Обе заданные точки должны лежать на окружности.'),('Найди окружность на новых данных','Пусть A=(−1;0), B=(3;0), а центр лежит на y=x+1. Серединный перпендикуляр x=1 даёт S=(1;2). Теперь SA²=4+4=8.','Два независимых линейных условия определяют новый центр.')]
        newpts={'A':(-1,0),'B':(3,0)};newcenter=(1,2);newq=8
    elif part=='а':
        points={'A':(1,-4),'B':(4,5),'C':(3,-2)};src='Найди окружность через A=(1;−4), B=(4;5), C=(3;−2).'
        center=(F(-7,2),F(5,2));q=F(125,2);constraints=[(1,1,1),(1,3,-4)]
        steps=[('Выведи две прямые центров','Пусть S=(u;v). Из SA²=SC² после сокращения квадратов получаем u+v=−1. Из SA²=SB² получаем u+3v=4.','Оба уравнения линейны, так как квадраты неизвестных сокращаются.'),('Определи центр и квадрат радиуса','Вычитание двух равенств даёт 2v=5, поэтому v=5/2, u=−7/2. К точке A смещение (9/2;−13/2): квадрат длины (81+169)/4=125/2. Значит, (x+7/2)²+(y−5/2)²=125/2.','Для окружности достаточно одного радиуса, но проверь оставшиеся точки подстановкой.'),('Проверь новый треугольник','Для A=(0;0), B=(4;0), C=(0;2) два серединных перпендикуляра x=2 и y=1 пересекаются в S=(2;1). От каждой вершины до S квадрат расстояния равен 5.','Для горизонтальной либо вертикальной хорды можно сразу описать её серединный перпендикуляр.')]
        newpts={'A':(0,0),'B':(4,0),'C':(0,2)};newcenter=(2,1);newq=5
    else:
        points={'A':(3,-7),'B':(8,-2),'C':(6,2)};src='Найди окружность через A=(3;−7), B=(8;−2), C=(6;2).'
        center=(3,-2);q=25;constraints=[(1,1,-1),(1,3,3)]
        steps=[('Приравняй квадраты расстояний','Из SA²=SB² получается u+v=1. Из SA²=SC² получается u+3v=−3. Это уравнения двух серединных перпендикуляров.','Порядок точек при вычитании выбери одинаковым для обеих координат.'),('Проверь все вершины','Из 2v=−4 следует v=−2 и u=3. Длины SA и SB равны 5 вдоль осей. Для C относительно S смещение (3;4), квадрат 25. Уравнение (x−3)²+(y+2)²=25.','Третья вершина действительно находится на окружности.'),('Перестрой на свежих данных','Для A=(−2;1), B=(2;1), C=(0;3) центр S=(0;1), поскольку три смещения от S равны (−2;0), (2;0), (0;2). Новый квадрат радиуса 4.','На новом рисунке не оставляй прежний центр.')];newpts={'A':(-2,1),'B':(2,1),'C':(0,3)};newcenter=(0,1);newq=4
    before=shape('Заданные точки и условия на центр',points,constraints)
    after=shape('Проверка исходной окружности',points,edges=[('S',k) for k in points],circles=[('S',center,q)])
    fresh=shape('Новые данные для построения',newpts,edges=[('S',k) for k in newpts],circles=[('S',newcenter,newq)])
    reason=f'У окружности центр S={text(center)}, квадрат радиуса {number(q)}. Её уравнение {equation(center,q)}. Для каждой заданной точки сумма квадратов смещений относительно S даёт одну и ту же правую часть.'
    c=entry(n,part,src+(' Составь её уравнение.' if n==1088 else ''),reason,'Запиши равенства расстояний от искомого центра до заданных точек. Для двух точек и заданной прямой второе условие уже дано.',steps,[before,after,fresh],[('Какова ордината исходного центра?',str(center[1]),'Реши систему двух прямых, не меняя знак ординаты.'),('Каков новый квадрат радиуса?',str(newq),'Подставь в формулу расстояния одну из новых точек и новый центр.')])
    c=final_equation(c,center,q);return c

def triangle_equations(part):
    pts={'A':(-7,5),'B':(3,-1),'C':(5,3),'K':(-2,2),'L':(4,1),'M':(-1,4)}
    fresh={'A':(0,0),'B':(4,0),'C':(0,2),'K':(2,0),'L':(2,1),'M':(0,1)}
    if part=='а':
        target='серединные перпендикуляры к AB, BC, CA'
        equations=[(5,-3,16),(1,2,-6),(6,-1,10)];alt=[(1,0,-2),(2,-1,-3),(0,1,-1)]
        first='Середины сторон имеют координаты K=(−2;2), L=(4;1), M=(−1;4). У равноудалённых от A и B точек после сокращения квадратов получается 5x−3y+16=0. Эта прямая проходит через K.'
        second='Для BC из равенства расстояний получается x+2y−6=0, а для CA — 6x−y+10=0. Они проходят через L и M соответственно. Для проверки можно подставить каждую середину и вторую равноудалённую точку.'
        third='У нового треугольника A=(0;0), B=(4;0), C=(0;2) перпендикуляр к AB имеет вид x=2, к BC — 2x−y−3=0, к CA — y=1.'
        asks=[('Какой свободный член у первого примитивного уравнения 5x−3y+c=0?','16','Подставь середину K=(−2;2).'),('Какова абсцисса всех точек нового серединного перпендикуляра к AB?','2','Для горизонтальной хорды он вертикален и проходит через K.')]
    elif part=='б':
        target='прямые AB, BC, CA';equations=[(3,5,-4),(2,-1,-7),(1,6,-23)];alt=[(0,1,0),(1,2,-4),(1,0,0)]
        first='У AB смещение (10;−6). Требуемый коэффициент наклона −3/5. Запись 3x+5y+c=0 с A=(−7;5) даёт c=−4.'
        second='Обе координаты B и C удовлетворяют 2x−y−7=0; A и C удовлетворяют x+6y−23=0. Подстановки двух различных точек достаточны, чтобы подтвердить каждую прямую.'
        third='В новом треугольнике A=(0;0), B=(4;0), C=(0;2) стороны лежат на y=0, x+2y−4=0 и x=0. Последняя вертикальна: запись y=kx+d для неё невозможна.'
        asks=[('Каков свободный член у 3x+5y+c=0 для исходной AB?','-4','Подставь A=(−7;5).'),('Чему равна ордината новой BC при x=2?','1','Подставь x=2 в x+2y−4=0.')]
    else:
        target='прямые, содержащие средние линии, параллельные AB, BC, CA'
        equations=[(3,5,-17),(2,-1,6),(1,6,-10)];alt=[(0,1,-1),(1,2,-2),(1,0,-2)]
        first='У LM направление AB. Подставь L=(4;1) в 3x+5y+c=0: c=−17. Точка M=(−1;4) удовлетворяет тому же уравнению.'
        second='Для MK берём направление BC и точку K=(−2;2): получаем 2x−y+6=0. Для KL направление CA даёт x+6y−10=0. В каждой паре проверяются обе середины.'
        third='У нового треугольника A=(0;0), B=(4;0), C=(0;2) середины K=(2;0), L=(2;1), M=(0;1). По ним получаются LM: y=1, MK: x+2y−2=0, KL: x=2.'
        asks=[('Каков свободный член первого исходного уравнения 3x+5y+c=0?','-17','Подставь L=(4;1).'),('Какова абсцисса новой прямой KL?','2','Проверь ординаты и абсциссы K и L; у обеих одна абсцисса.')]
    checks=[line_text(eq) for eq in equations]
    explain='В указанном порядке: '+', '.join(checks)+'.'
    first_graph=shape('Одна из исходных прямых',pts,[equations[0]],edges=[('A','B'),('B','C'),('C','A')])
    all_graph=shape('Все три исходные прямые',pts,equations,edges=[('A','B'),('B','C'),('C','A')])
    changed=shape('Тот же вопрос к другому треугольнику',fresh,alt,edges=[('A','B'),('B','C'),('C','A')])
    c=entry(1090,part,'Даны A=(−7;5), B=(3;−1), C=(5;3). Составь в указанном порядке уравнения, задающие '+target+'.',explain,'Различай прямую стороны, параллельную ей среднюю линию и серединный перпендикуляр. Укажи точки, через которые должна пройти именно нужная прямая.',[('Построй первую прямую',first,'Проверь уравнение подстановкой выбранной точки.'),('Получай оставшиеся две',second,'Следи за порядком AB, BC, CA.'),('Реши для другого треугольника',third,'Вертикальные и горизонтальные прямые также имеют уравнение ax+by+c=0.')],[first_graph,all_graph,changed],asks)
    accepted=[]
    for gap,separator in product(('',' '),('|',' | ')):
        accepted.append(separator.join((';'+gap).join(str(x) for x in eq) for eq in equations))
        accepted.append(separator.join(checks))
    c['answer']=dict(mode='exact',prompt='Введи три примитивные тройки a;b;c уравнений ax+by+c=0 в указанном порядке через |. Сократи общий множитель; первый ненулевой коэффициент положителен.',accepted=list(dict.fromkeys(accepted)),feedback='Проверь, что названы все три прямые именно этого подпункта. Первые коэффициенты определяют направление, а свободный член — положение.')
    return c


def parallel():
    pts={'A':(F(-1,3),0),'B':(F(2,3),2),'C':(F(3,2),0),'D':(F(5,2),2)}
    eqs=[(6,-3,2),(2,-1,-3)]
    more=[(-1,1,-1),(-1,1,2)]
    c=entry(1091,None,'Докажи, что прямые 3x−1,5y+1=0 и 2x−y−3=0 параллельны. Убедись, что они различны.',
        'Получаем y=2x+2/3 и y=2x−3. У обеих прямых наклон 2, а ординаты пересечения с Oy различаются. При одном x ординаты отличаются на 11/3, общих точек нет.',
        'Вырази y в обоих равенствах, сохрани знак и свободный член. Одинакового наклона мало для различия с совпадением.',
        [('Приведи первое уравнение к виду y=kx+d','Имеем 1,5y=3x+1, поэтому y=2x+2/3. Продвижение на единицу вправо увеличивает ординату на 2.','Делятся оба слагаемых правой части.'),('Сравни линии','У второй y=2x−3. Разность ординат постоянна и равна 2/3+3=11/3. Следовательно, прямые различны и нигде не пересекаются.','Если равны ещё и свободные члены, получаются совпадающие прямые.'),('Проверь другую пару','У y=x+1 и y=x−2 наклон 1, разность ординат 3. Эти прямые тоже различны и параллельны.','Проверь разность на произвольном x, а не только в начале координат.')],
        [shape('Первая прямая и две точки',{'A':pts['A'],'B':pts['B']},eqs[:1]),shape('Две исходные прямые',pts,eqs),shape('Новая пара с другим наклоном',{'A':(0,1),'B':(0,-2)},more)],[('Каков общий наклон исходных прямых?','2','У первого уравнения раздели 3 на 1,5.'),('Какова разность ординат новой пары при одном x?','3','Вычти x−2 из x+1.')],(99,))
    return c


def collinear(part):
    records={
      'а':({'A':(-2,0),'B':(3,F(5,2)),'C':(6,4)},(1,-2,2), 'По A и B наклон равен (5/2)/(5)=1/2. Прямая задаётся x−2y+2=0. Для C=(6;4) получаем 6−8+2=0.', '2','4'),
      'б':({'A':(3,10),'B':(3,12),'C':(3,-6)},(1,0,-3),'Все три абсциссы равны 3, так что точки лежат на вертикали x=3. При попытке считать наклон возникло бы деление на 0.', '3','3'),
      'в':({'A':(1,2),'B':(2,5),'C':(-10,-31)},(3,-1,-1),'Из A и B наклон 3. Подстановка A в y=3x+d даёт d=−1. Для C=(−10;−31) верно 3·(−10)−1=−31.', '3','-31')}
    pts,eq,why,one,unused=records[part]
    # For the long third example one grid interval denotes five coordinate units.
    scale=5 if part=='в' else 1
    def scaled(label,coords,coeff):
        vals={k:(v[0]/scale,v[1]/scale) for k,v in coords.items()};a,b,c=coeff
        return shape(label,vals,[(a*scale,b*scale,c)])
    on=scaled('Три исходные точки на одной прямой',pts,eq);ab=scaled('Определи прямую по A и B',{k:pts[k] for k in 'AB'},eq)
    if part=='б':
        other={'A':(-2,2),'B':(-2,-4),'T':(-1,1)};new_eq=(1,0,2)
        change='При A=(−2;2), B=(−2;−4) прямая вертикальна и имеет x=−2. Точка T=(−1;1) не принадлежит ей: её абсцисса иная.';last='-2'
    else:
        other={'A':(-1,-1),'B':(2,5),'T':(1,2)};new_eq=(2,-1,1);last='3'
        change='Для новых A=(−1;−1), B=(2;5) получаем y=2x+1. При x=1 линия требует y=3, поэтому T=(1;2) вне неё.'
    new=scaled('Новая третья точка вне прямой',other,new_eq)
    if part=='в':
        other={'A':(-5,-5),'B':(10,25),'T':(5,10)};new_eq=(2,-1,5);last='15'
        change='Для новых A=(−5;−5), B=(10;25) получаем y=2x+5. При x=5 требовалась бы ордината 15, поэтому T=(5;10) вне прямой.'
        new=scaled('Новая третья точка вне прямой',other,new_eq)
    firstq=('Какова абсцисса каждой точки исходной вертикали?' if part=='б' else 'Какую ординату требует исходная прямая при x=2?' if part=='а' else 'Каков наклон исходной прямой?')
    newq='Какова абсцисса точек новой прямой?' if part=='б' else 'Какую ординату требует новая прямая при x=5?' if part=='в' else 'Какую ординату требует новая прямая при x=1?'
    c=entry(1092,part,'По координатам '+', '.join(k+'='+text(v) for k,v in pts.items())+' докажи, что все три точки лежат на одной прямой.',why,'Сначала определи прямую по двум различным точкам. Затем подставь в её уравнение третью точку. При равных абсциссах выбери вертикаль.',
        [('Построй прямую AB',why,'Двух различных точек достаточно для задания одной прямой.'),('Проверь точку C',f'Уравнение {line_text(eq)} выполняется для A, B и C. Подстановка C={text(pts["C"])} даёт ноль в левой части, поэтому C принадлежит той же самой AB.','Проверить нужно именно третью точку, после того как прямая уже зафиксирована.'),('Проверь, всегда ли это работает',change,'Одной новой неудачной подстановки достаточно, чтобы исключить принадлежность.')],[ab,on,new],[(firstq,one,'Проверь коэффициенты своей прямой и сравни координаты A и B.'),(newq,last,'Подставь указанную абсциссу в наклонную прямую или прочитай фиксированный x у вертикали.')],(99,))
    if scale!=1:
        note='Одна клетка соответствует 5 единицам координат. Сравни наклон и подстановку точек в уравнение.';c['visualization']['caption']=note;c['visualization']['model']['description']=note
    return c


def build():return {'bookId':BOOK,'lessons':classify()+[through_points(1088),through_points(1089,'а'),through_points(1089,'б')]+[triangle_equations(p) for p in 'абв']+[parallel()]+[collinear(p) for p in 'абв']}


if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true');opts=parser.parse_args();data=json.dumps(build(),ensure_ascii=False,separators=(',',':'))+'\n'
    if opts.check:assert OUT.read_text()==data
    else:OUT.write_text(data)
